import hashlib,json,math,platform,time
from pathlib import Path
from quantage.contracts import verify_external,normalize_problem
path=Path("runs/20261113-c05-semantic-contracts/external-contract-audit.json")
doc=json.loads(path.read_text())
def decode(v):
    if isinstance(v,dict):
        if set(v)=={"$float"}:return float(v["$float"])
        return {k:decode(x) for k,x in v.items()}
    if isinstance(v,list):return [decode(x) for x in v]
    return v
def encode(v):
    if isinstance(v,float) and not math.isfinite(v):return {"$float":"nan" if math.isnan(v) else "inf" if v>0 else "-inf"}
    if isinstance(v,dict):return {k:encode(x) for k,x in v.items()}
    if isinstance(v,(list,tuple)):return [encode(x) for x in v]
    return v
def hashes():return {s:hashlib.sha256(Path(s).read_bytes()).hexdigest() for s in doc["audited_files"]}
started=time.perf_counter();before=hashes();rows=[]
for raw in doc["cases"]:
    case=decode(raw)
    try:
        result=verify_external(case["problem"],case["proposal"],case["tolerance"])
        match=result["valid"]==case["expected_valid"] and result["stage"]==case["expected_stage"]
    except Exception as exc:result={"exception":type(exc).__name__,"message":str(exc)};match=False
    try:normalization={"normalized":normalize_problem(case["problem"])}
    except Exception as exc:normalization={"exception":type(exc).__name__,"message":str(exc)}
    rows.append({"id":case["id"],"result":result,"expectation_matches":match,"problem_normalization":normalization})
print(json.dumps(encode({"results":rows,"input_hashes_before":before,"input_hashes_after":hashes(),"runtime_seconds":time.perf_counter()-started,"python":platform.python_version(),"platform":platform.platform()}),sort_keys=True,allow_nan=False))
